class SbomTest(unittest.TestCase):
    def build(self, **kw):
        return sbom.build_sbom(lock_text=LOCK, pubspec_text="version: 0.1.0-dev+1\n",
                               flutter=sbom.parse_flutter_json(FLUTTER),
                               now=dt.datetime(2026, 11, 2, tzinfo=dt.timezone.utc),
                               serial="00000000-0000-0000-0000-000000000000", **kw)

    def by_name(self, doc):
        return {c["name"]: c for c in doc["components"]}

    def test_dart_packages(self):
        self.assertEqual(self.build(build_number="560")["metadata"]["component"]["version"],
                         "0.1.0-dev+560")
        doc = self.build(platform="web", build="main@abc1234")
        self.assertEqual(doc["bomFormat"], "CycloneDX")
        self.assertEqual(doc["specVersion"], "1.5")
        self.assertEqual(doc["metadata"]["component"]["version"], "0.1.0-dev+1")
        c = self.by_name(doc)
        self.assertEqual(c["http"]["purl"], "pkg:pub/http@1.5.0")
        self.assertEqual(c["http"]["hashes"][0]["alg"], "SHA-256")
        self.assertEqual(c["meta"]["purl"], "pkg:pub/meta@1.16.0")
        self.assertNotIn("hashes", c["meta"])  # malformed hash left out
        # Local plugin of third_party/: no purl (no false match on pub.dev).
        self.assertNotIn("purl", c["flutter_secure_storage_windows"])
        self.assertEqual(c["flutter_secure_storage_windows"]["version"], "3.1.2")
        # SDK package: version of the Flutter SDK; dev dependency excluded.
        self.assertEqual(c["flutter"]["version"], "3.38.1")
        self.assertEqual(c["flutter_lints"]["scope"], "excluded")
        self.assertEqual(c["dart-sdk"]["version"], "3.10.0")
        deps = doc["dependencies"][0]["dependsOn"]
        self.assertIn("pkg:pub/http@1.5.0", deps)
        self.assertNotIn("pkg:pub/meta@1.16.0", deps)  # transitive
        refs = [x["bom-ref"] for x in doc["components"]]
        self.assertEqual(len(refs), len(set(refs)))
        json.dumps(doc)

    def test_gradle(self):
        deps = sbom.parse_gradle_deps(GRADLE)
        self.assertIn(("androidx.core", "core", "1.15.0"), deps)
        self.assertIn(("androidx.car.app", "app", "1.4.0"), deps)
        self.assertIn(("androidx.lifecycle", "lifecycle-runtime", "2.6.1"), deps)
        self.assertIn(("io.flutter", "flutter_embedding_release", "1.0.0-1a2b3c"), deps)
        names = [a for _, a, _ in deps]
        self.assertNotIn("kotlin-stdlib", names)  # constraint (c)
        self.assertNotIn("not-resolved", names)  # (n)
        doc = self.build(gradle_text=GRADLE)
        self.assertEqual(self.by_name(doc)["firebase-messaging"]["purl"],
                         "pkg:maven/com.google.firebase/firebase-messaging@24.1.0")

    def test_podfile(self):
        pods, local = sbom.parse_podfile_lock(PODFILE)
        self.assertEqual(dict(pods), {"Firebase": "11.15.0", "Flutter": "1.0.0",
                                      "GoogleUtilities": "8.1.0", "sarcade_compass": "0.0.1"})
        self.assertEqual(local, {"Flutter", "sarcade_compass"})
        c = self.by_name(self.build(podfile_text=PODFILE))
        self.assertEqual(c["Firebase"]["purl"], "pkg:cocoapods/Firebase@11.15.0")
        self.assertNotIn("purl", c["sarcade_compass"])

    def test_cli_missing_optional_inputs(self):
        tmp = Path(self._testMethodName + ".tmp")
        tmp.mkdir(exist_ok=True)
        try:
            (tmp / "pubspec.lock").write_text(LOCK, encoding="utf-8")
            out = tmp / "out" / "sarcade-app.cdx.json"
            rc = sbom.main(["--lock", str(tmp / "pubspec.lock"), "--pubspec", str(tmp / "none.yaml"),
                            "--gradle-deps", str(tmp / "none.txt"), "--out", str(out)])
            self.assertEqual(rc, 0)
            self.assertEqual(json.loads(out.read_text())["metadata"]["component"]["version"], "0.0.0")
        finally:
            for p in sorted(tmp.rglob("*"), reverse=True):
                p.rmdir() if p.is_dir() else p.unlink()
            tmp.rmdir()


