class FakeGitHub(osv_nightly.GitHub):
    def __init__(self, issues):
        super().__init__("o/r", "t")
        self.issues, self.calls = issues, []

    def call(self, method, path, data=None):
        self.calls.append((method, path, data))
        if method == "GET" and "/issues?" in path:
            return self.issues
        if method == "POST" and path.endswith("/issues"):
            return {"number": 7}
        return {}


class OsvTest(unittest.TestCase):
    def test_findings_grouped(self):
        f = osv_nightly.findings_from_reports({"web-dev": REPORT, "main": REPORT})
        self.assertEqual(len(f), 1)
        self.assertEqual(f[0]["id"], "GHSA-jfh8-c2jp-5v3q")
        self.assertEqual(f[0]["fixed"], ["2.15.0"])
        self.assertEqual(f[0]["seen_in"], ["web-dev", "main"])
        self.assertEqual(f[0]["severity"], "10.0")

    def test_issue_lifecycle(self):
        f = osv_nightly.findings_from_reports({"main": REPORT})
        body = osv_nightly.issue_body(f, ["main"], "", today=dt.date(2026, 11, 2))
        self.assertEqual(osv_nightly.keys_in_body(body), {osv_nightly.finding_key(f[0])})
        # Nothing open: one issue opened, with the label.
        gh = FakeGitHub([])
        self.assertEqual(osv_nightly.sync_issue(gh, f, body), "issue #7 opened")
        post = [c for c in gh.calls if c[0] == "POST" and c[1].endswith("/issues")][0]
        self.assertEqual(post[2]["labels"], ["security"])
        self.assertEqual(post[2]["title"], "Faille dans un composant")
        # Same list: no duplicate, no change.
        existing = {"number": 3, "title": "Faille dans un composant", "body": body}
        gh = FakeGitHub([existing, {"number": 4, "title": "Autre"}])
        self.assertEqual(osv_nightly.sync_issue(gh, f, body), "issue #3 unchanged")
        self.assertFalse([c for c in gh.calls if c[0] != "GET"])
        # New list: body updated and one comment (e-mail to the owner).
        gh = FakeGitHub([dict(existing, body="old")])
        self.assertEqual(osv_nightly.sync_issue(gh, f, body), "issue #3 updated")
        self.assertEqual([c[0] for c in gh.calls if c[0] != "GET"], ["PATCH", "POST"])
        # Nothing left: closed.
        gh = FakeGitHub([existing])
        self.assertEqual(osv_nightly.sync_issue(gh, [], ""), "issue #3 closed")
        self.assertEqual(gh.calls[-1][2]["state"], "closed")
        gh = FakeGitHub([])
        self.assertEqual(osv_nightly.sync_issue(gh, [], ""), "nothing found, no open issue")

    def test_check_config(self):
        today = dt.date(2026, 11, 2)
        self.assertEqual(osv_nightly.check_config("", today), ([], []))
        good = ('[[IgnoredVulns]]\nid = "GHSA-x"\nignoreUntil = 2027-01-31\n'
                'reason = "Code path not used by SARCADE"\n')
        self.assertEqual(osv_nightly.check_config(good, today), ([], []))
        errors, _ = osv_nightly.check_config('[[IgnoredVulns]]\nid = "GHSA-x"\n', today)
        self.assertEqual(len(errors), 2)  # reason and ignoreUntil
        _, notes = osv_nightly.check_config(good.replace("2027-01-31", "2026-10-01"), today)
        self.assertIn("passed", notes[0])

    def test_repo_register_valid(self):
        path = Path(__file__).resolve().parent.parent / "osv-scanner.toml"
        errors, _ = osv_nightly.check_config(path.read_text(encoding="utf-8"))
        self.assertEqual(errors, [])


